<section><h2>Engine availability</h2><table id="ch-engines"><tbody></tbody></table><p>Availability and verified functionality are separate. Refreshing this page starts no search or installation.</p></section>
<section><h2>Analysis and research jobs</h2><table id="ch-jobs"><tbody></tbody></table></section>
</div></div>
<script>
(()=>{'use strict';const base=<?php echo json_encode($base,JSON_HEX_TAG|JSON_HEX_AMP);?>,token=<?php echo json_encode(Session::getFormToken());?>;
const api=async(path,method='GET',data)=>{const r=await fetch(base+encodeURIComponent('/api/v1'+path)+(method==='GET'?'':'&'+encodeURIComponent(token)+'=1'),{method,headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.message||v.error||'Request failed');return v;};
const text=(tag,value)=>{const e=document.createElement(tag);e.textContent=String(value??'');return e;};
const rows=(id,items)=>{const body=document.querySelector(id+' tbody');body.replaceChildren();for(const item of items){const tr=document.createElement('tr');for(const value of item)tr.append(text('td',value));body.append(tr);}};
async function loadCollection(form){const name=form.dataset.collection,r=await api('/admin/content/'+name),items=r.items||r[name]||[];form._items=items;const select=form.elements.select;select.replaceChildren(new Option('Create a new item',''));for(const item of items)select.add(new Option(item.title||item.id,item.id));}
for(const form of document.querySelectorAll('form[data-collection]')){form.elements.select.addEventListener('change',()=>{const item=(form._items||[]).find(x=>x.id===form.elements.select.value);if(!item){form.reset();return;}for(const key of ['id','title','fen','level','kind'])form.elements[key].value=item[key]||'';form.elements.body.value=item.body||item.objective||'';form.elements.moves.value=(item.solution||item.moves||[]).join(' ');});form.addEventListener('submit',async e=>{e.preventDefault();const message=form.querySelector('.message');try{const fields=Object.fromEntries(new FormData(form));delete fields.select;const moves=fields.moves.trim().split(/\s+/).filter(Boolean);fields.moves=moves;fields.solution=moves;fields.objective=fields.body;fields.category=fields.level;await api('/admin/content/'+form.dataset.collection,'POST',fields);message.textContent='Revision saved and validated.';await loadCollection(form);}catch(err){message.textContent=err.message;}});}
document.querySelector('#ch-settings').addEventListener('submit',async e=>{e.preventDefault();const form=e.target;try{const values=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));await api('/admin/settings','POST',values);form.querySelector('.message').textContent='Settings saved.';}catch(err){form.querySelector('.message').textContent=err.message;}});
async function refresh(){const status=document.querySelector('#ch-status');try{const s=await api('/system/status');status.textContent='Connected · '+(s.version||s.product_version||'0.1.0-development')+' · independent chess backend';const engines=await api('/engines');rows('#ch-engines',(engines.engines||engines.items||[]).map(x=>[x.name||x.id,x.status||x.available,x.version||'']));const jobs=await api('/admin/jobs');const jobRows=[...(jobs.items||jobs.jobs||[]),...(jobs.analysis||[])];rows('#ch-jobs',jobRows.slice(0,40).map(x=>[x.id,x.status,x.kind||x.type||'analysis']));const settings=await api('/admin/settings');for(const [k,v]of Object.entries(settings.settings||settings)){if(document.querySelector('#ch-settings').elements[k])document.querySelector('#ch-settings').elements[k].value=v;}await Promise.all([...document.querySelectorAll('form[data-collection]')].map(loadCollection));}catch(err){status.textContent=err.message;}}
document.querySelector('#ch-refresh').addEventListener('click',refresh);refresh();})();
</script>
